<?php
/** Real WordPress/Woo qualification in disposable native schemas, never customer data. */
function kiwe_mcp_design_native_tests(callable $check,callable $ledger,string $run,string $mode): array {
 if(PHP_SAPI!=='cli'||!preg_match('/^[a-f0-9]{16}$/D',$run)||!in_array($mode,['normal','plain'],true))throw new RuntimeException('Exact native authoring qualification context required.');
 global $wpdb;$actor=get_current_user_id();$owner=DSA\Access\Site_Owner_Service::owner_id();$sandbox=new Kiwe_MCP_Native_Table_Sandbox($run);$started=false;$filters=[];$mediaRoot=KIWE_M02['private'].'/media-'.$run;
 $nativeRecords=static function():array{global$wpdb;$hashes=[];$bytes=0;foreach(['posts'=>['ID'],'postmeta'=>['meta_id'],'terms'=>['term_id'],'term_taxonomy'=>['term_taxonomy_id'],'term_relationships'=>['object_id','term_taxonomy_id'],'users'=>['ID'],'usermeta'=>['umeta_id'],'comments'=>['comment_ID'],'commentmeta'=>['meta_id']]as$name=>$keys){$table=$wpdb->$name;if(!preg_match('/^[a-zA-Z0-9_]+$/D',$table))throw new RuntimeException('Exact native preservation table required.');$hash=hash_init('sha256');$offset=0;do{$rows=$wpdb->get_results("SELECT * FROM `{$table}` ORDER BY ".implode(',',array_map(static fn($key)=>'`'.$key.'`',$keys)).' LIMIT 250 OFFSET '.$offset,ARRAY_A);foreach($rows as$row){$value=serialize($row);$bytes+=strlen($value);if($bytes>67108864)throw new RuntimeException('Native preservation exceeds the private64MiB qualification budget.');hash_update($hash,$value);}$offset+=count($rows);if($offset>250000)throw new RuntimeException('Native preservation exceeds the bounded record budget.');}while(count($rows)===250);$hashes[$name]=['rows'=>$offset,'sha256'=>hash_final($hash)];}return$hashes;};
 $snapshot=static function()use($nativeRecords):array{global$wpdb;$rows=$wpdb->get_results("SELECT option_name,option_value,autoload FROM {$wpdb->options} WHERE option_name IN ('dsa_settings','pk_settings_v3','stp_settings','kiwe_seam_design_context_v1','active_plugins','kiwe_store_app_enabled_v1','kiwe_seo_workspace_enabled_v1','kiwe_guest_app_enabled_v1','kiwe_ai_app_enabled_v1','kiwe_sitegraph_app_enabled_v1','kiwe_mcp_app_enabled_v1','kiwe_mcp_revocation_epoch_v1') ORDER BY option_name",ARRAY_A);return['controls'=>hash('sha256',wp_json_encode($rows)),'mcpRows'=>(int)$wpdb->get_var('SELECT COUNT(*) FROM '.DSA\MCP\Records::table()),'nativeRecords'=>$nativeRecords(),'phonekey'=>hash_file('sha256',DSA_DIR.'includes/PhoneKey/phonekey-core.php')];};$before=$snapshot();$ledger('original-record-hashes',$before['nativeRecords']);
 $denied=static function(callable $work,string $label)use($check){$refused=false;try{$v=$work();$refused=is_wp_error($v);}catch(Throwable){$refused=true;}$check($refused,$label);};
 $grant=static function($r,array $scopes)use($owner){wp_set_current_user($owner);$auth=new DSA\MCP\Authorization_Service($r);$client=$auth->register_client(['client_name'=>'M07 isolated native fixture','redirect_uris'=>['http://127.0.0.1:19384/callback'],'grant_types'=>['authorization_code','refresh_token'],'response_types'=>['code'],'token_endpoint_auth_method'=>'none']);$verifier=DSA\MCP\Credentials::secret();$secret=DSA\MCP\Credentials::secret();$params=['client_id'=>$client['client_id'],'redirect_uri'=>$client['redirect_uris'][0],'response_type'=>'code','code_challenge_method'=>'S256','code_challenge'=>rtrim(strtr(base64_encode(hash('sha256',$verifier,true)),'+/','-_'),'='),'resource'=>DSA\MCP\Urls::resource(),'state'=>'m07-native-fixture','scope'=>implode(' ',$scopes)];$id=$auth->begin($params,$secret);$auth->review($id,$secret,$owner);$code=$auth->approve($id,$secret,$owner,true,false);$tokens=$auth->exchange(['client_id'=>$client['client_id'],'grant_type'=>'authorization_code','code'=>$code['code'],'redirect_uri'=>$client['redirect_uris'][0],'code_verifier'=>$verifier,'resource'=>DSA\MCP\Urls::resource()]);DSA\MCP\Auth_Context::establish($auth,$tokens['access_token']);return[$auth,$tokens['access_token']];};
 try{
  $info=$sandbox->start($owner);$started=true;$ledger('sandbox',$info);wp_set_current_user(0);wp_set_current_user($owner);
  $check(!$info['customersCopied']&&$info['tables']>20,'Design qualification uses empty native schemas and only its technical actor');
  update_option('kiwe_mcp_app_enabled_v1','1',false);update_option(DSA\Apps\AI_App_Service::option(),'0',false);update_option('kiwe_store_app_enabled_v1',$mode==='normal'?'1':'0',false);update_option('kiwe_seo_workspace_enabled_v1','0',false);update_option(DSA\Apps\SiteGraph_App_Service::option(),'0',false);
  $registry=static function(){ $r=new DSA\MCP\Operation_Registry();DSA\MCP\Native_Provider::register($r);do_action('kiwe_mcp_register_providers',$r,DSA\Apps\MCP_Provider_Contract::API);return$r;};$r=$registry();$scopes=['mcp.read','mcp.design.read'];
  $check(count($r->describe($scopes))===2,'Only connection facts and the separately scoped design read are selected');
  [$auth,$bearer]=$grant($r,$scopes);
  $read=static function(array$args)use($r){$g=DSA\MCP\Auth_Context::current();$v=$r->read('mcp.design.read',$args,$g['scopes'],$g['pins']);if(is_wp_error($v))throw new RuntimeException('Native design read refused: '.$v->get_error_message());return json_decode($v['resultJson'],true,32,JSON_THROW_ON_ERROR);};
  $assemble=static function(array$args)use($read,$check){$first=$read($args);$bytes='';$parts=[];for($part=0;$part<$first['parts'];$part++){$piece=$part===0?$first:$read($args+['part'=>$part,'expected'=>$first['sha256']]);$check($piece['part']===$part&&$piece['sha256']===$first['sha256']&&$piece['bytes']===$first['bytes'],'Same native design revision '.$args['area'].' part'.$part);$decoded=base64_decode($piece['dataBase64'],true);if($decoded===false)throw new RuntimeException('Native binary part invalid');$bytes.=$decoded;$parts[]=$piece;}$check(strlen($bytes)===$first['bytes']&&hash('sha256',$bytes)===$first['sha256'],'Complete exact native design bytes '.$args['area']);return[json_decode($bytes,true,512,JSON_THROW_ON_ERROR),$parts];};
  $guide=$read(['area'=>'guide']);$check($guide['storeAvailable']===($mode==='normal')&&$guide['start']['entry']==='https://start.kiwelaunch.com/start.md','Guide uses current applicability and canonical Start without a fabricated pin');
  $check(!DSA\Apps\AI_App_Service::enabled()&&!DSA\Apps\SEO_App_Service::enabled()&&!DSA\Apps\SiteGraph_App_Service::enabled(),'Core design handoff needs none of the optional AI/SEO/SiteGraph Apps');
  $public=wp_insert_post(['post_type'=>'post','post_status'=>'publish','post_title'=>'M07 PUBLIC article','post_content'=>'<p>Native public preview content.</p>','post_author'=>$owner],true);$private=wp_insert_post(['post_type'=>'post','post_status'=>'private','post_title'=>'M07 PRIVATE article','post_content'=>'M07 PRIVATE CONTENT','post_author'=>$owner],true);$password=wp_insert_post(['post_type'=>'post','post_status'=>'publish','post_password'=>'m07-synthetic-password','post_title'=>'M07 PASSWORD article','post_content'=>'M07 PASSWORD CONTENT','post_author'=>$owner],true);
  $check(is_int($public)&&is_int($private)&&is_int($password),'Native public/private/password fixtures are isolated');update_post_meta($public,'private_api_key','M07 PRIVATE META');
  if($mode==='normal'){
   update_option('woocommerce_weight_unit','kg',false);$weighted=new WC_Product_Simple();$weighted->set_name('M07 PUBLIC weighted product');$weighted->set_status('publish');$weighted->set_regular_price('25');$weighted->set_weight('0.25');$weightedId=$weighted->save();
   [$weights]=$assemble(['area'=>'catalogue','resource'=>'products','search'=>'M07 PUBLIC weighted product']);$pack=$weights['data'][0]['product']??[];
   $check(($pack['id']??0)===$weightedId&&($pack['weight']??null)==='0.25'&&($pack['weightUnit']??null)==='kg'&&($pack['weightText']??null)===html_entity_decode(wp_strip_all_tags(wc_format_weight('0.25')),ENT_QUOTES),'Native public product evidence preserves actual pack weight and native display units');
   $weighted->set_weight('');$weighted->save();[$emptyWeight]=$assemble(['area'=>'catalogue','resource'=>'products','search'=>'M07 PUBLIC weighted product']);$check(($emptyWeight['data'][0]['product']['weight']??null)===''&&($emptyWeight['data'][0]['product']['weightText']??null)==='','An unset pack weight stays unknown rather than becoming zero or an invented pack');$weighted->set_weight('0.25');$weighted->save();
  }
  [$graph,$graphParts]=$assemble(['area'=>'sitegraph']);$text=wp_json_encode($graph);
  $check($graph['authority']['publicDataOnly']&&!$graph['authority']['mayMutateWordPress']&&$graph['authority']['captureMethod']==='scoped-mcp-public-projection','Native export retains public-only non-mutating authority');
  $check(isset($graph['siteGraph']['kiwe']['apps']['schema'])&&$graph['siteGraph']['kiwe']['apps']['schema']==='kiwe.app-capabilities.v1','Native SiteGraph carries the complete authoritative App capabilities');
  $check(str_contains($text,'M07 PUBLIC article')&&!str_contains($text,'M07 PRIVATE article')&&!str_contains($text,'M07 PASSWORD article')&&!str_contains($text,'M07 PRIVATE META'),'Graph includes public evidence and excludes protected records/private metadata');
  $check(isset($graph['seamDesignContext']['identity'],$graph['dynamicBindings']['fields'],$graph['forms'],$graph['links'],$graph['discussion']),'Complete Core facts, dynamic bindings and native interaction contracts remain available');
  $check(!isset($graph['generatedAt'],$graph['siteGraph']['calibration']['generatedAt']),'Only documented native capture clocks are removed');
  $check(preg_match('/^sha256:[a-f0-9]{64}$/D',$graph['revision']??'')===1,'Actual native graph carries the strict-map content revision');
  $first=$graphParts[0];$check($first['parts']>1,'The real native graph exercises multi-request continuation');$reread=$read(['area'=>'sitegraph','part'=>1,'expected'=>$first['sha256']]);$check($reread['dataBase64']===$graphParts[1]['dataBase64'],'Unchanged native facts remain stable across capture clocks');
  wp_update_post(['ID'=>$public,'post_title'=>'M07 CHANGED public article']);$denied(fn()=>$read(['area'=>'sitegraph','part'=>1,'expected'=>$first['sha256']]),'A concurrent native content edit refuses mixed-revision continuation');wp_update_post(['ID'=>$public,'post_title'=>'M07 PUBLIC article']);
  [$catalogue]=$assemble(['area'=>'catalogue','resource'=>'posts','page'=>1,'search'=>'M07']);$catalogueText=wp_json_encode($catalogue);$check(str_contains($catalogueText,'M07 PUBLIC article')&&!str_contains($catalogueText,'M07 PRIVATE article')&&!str_contains($catalogueText,'M07 PASSWORD article')&&!str_contains($catalogueText,'M07 PRIVATE META'),'Native public catalogue uses the same protected-content boundary');
  [$media]=$assemble(['area'=>'catalogue','resource'=>'media','page'=>1]);$check(($media['args']['contextOnly']??false)===true,'Media keeps native explicit/inherited design selection');
  [$framework]=$assemble(['area'=>'framework']);$check($framework['schema']==='kiwe.mcp-framework-evidence.v1'&&is_array($framework['tokens'])&&is_array($framework['bricksClasses']),'Actual native Framework vocabulary/tokens/classes are available without changing styles');
  $denied(fn()=>$read(['area'=>'sitegraph','part'=>1]),'A continuation without its first fingerprint refuses');$denied(fn()=>$read(['area'=>'catalogue','resource'=>'terms','taxonomy'=>'category','page'=>2]),'Unsupported native term pagination is not invented');
  if($mode==='normal'){
   update_option('kiwe_store_app_enabled_v1','0',false);$off=$read(['area'=>'guide']);$check(!$off['storeAvailable']&&!in_array('Shop',$off['pageChecklist'],true),'Store-off hides the commerce design checklist');$denied(fn()=>$read(['area'=>'catalogue','resource'=>'products']),'Store-off blocks its native product catalogue');[$offGraph]=$assemble(['area'=>'sitegraph']);$check(isset($offGraph['seamDesignContext']['identity']),'Store-off preserves Core business identity');update_option('kiwe_store_app_enabled_v1','1',false);
  }else{
   $check(!function_exists('WC')&&!class_exists('DSA\Commerce\MCP_Store_Authoring',false),'No-Woo design evidence loads no Store authoring adapter');$denied(fn()=>$read(['area'=>'catalogue','resource'=>'products']),'Non-Woo product catalogue refuses');
  }
  [$narrow]=$grant($r,['mcp.read']);$denied(fn()=>$read(['area'=>'guide']),'An actual earlier read-only native grant cannot gain design exports');
  update_option('kiwe_mcp_app_enabled_v1','0',false);$check($r->describe(['mcp.design.read'])===[],'App-Off removes current design discovery');update_option('kiwe_mcp_app_enabled_v1','1',false);
  $check($wpdb->last_error==='','Native design reads leave no database error');return['mode'=>$mode,'schemas'=>$info['tables'],'customerDataCopied'=>false,'nativeDesign'=>true,'actualClientConsent'=>false,'remoteGeneration'=>false,'realDeliveryPermitted'=>false];
 }finally{
  DSA\MCP\Auth_Context::clear();foreach(array_reverse($filters)as[$hook,$cb])remove_filter($hook,$cb,PHP_INT_MAX);
  if($started){$closed=$sandbox->close();$check($closed['remaining']===0&&$closed['retired']>20,'Every isolated native design table retires');$ledger('retired',$closed);}
  wp_set_current_user(0);wp_set_current_user($actor);$check($snapshot()===$before,'Original native controls, nine tables, grants and PhoneKey remain exact');
 }
